function maxEnergyBoost(energyDrinkA, energyDrinkB) {
  let drinkA = 0;
  let drinkB = 0;
  let cleanse = 0;
  for (let i = 0; i < energyDrinkA.length; i++) {
    const nextA = Math.max(drinkA, cleanse) + energyDrinkA[i];
    const nextB = Math.max(drinkB, cleanse) + energyDrinkB[i];
    cleanse = Math.max(drinkA, drinkB);
    drinkA = nextA;
    drinkB = nextB;
  }
  return Math.max(drinkA, drinkB);
}

