function maxEnergyBoost(energyDrinkA, energyDrinkB) {
  // plan(hour, drink): best energy from this hour on while drink is the one we may take without cleansing.
  // Each hour we either take that drink, or spend the hour cleansing and switch to the other drink.
  const gain = [energyDrinkA, energyDrinkB];
  const n = energyDrinkA.length;
  const plan = (hour, drink) => {
    if (hour === n) return 0;
    const stay = gain[drink][hour] + plan(hour + 1, drink);
    const swap = plan(hour + 1, 1 - drink);
    return Math.max(stay, swap);
  };
  return Math.max(plan(0, 0), plan(0, 1));
}

