function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? pick(1900, 2000) : pick(3, 10);
  const top = large ? 100000 : [3, 10, 100000][pick(0, 2)];
  const a = [], b = [];
  // Blocks where one drink is clearly better make switching worth considering.
  let favour = pick(0, 2);
  for (let i = 0; i < n; i++) {
    if (rand() < (large ? 0.01 : 0.3)) favour = pick(0, 2);
    const high = () => pick(Math.ceil(top / 2), top), any = () => pick(1, top);
    a.push(favour === 0 ? high() : any());
    b.push(favour === 1 ? high() : any());
  }
  return [a, b];
}
